def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    count = np.floor_divide(bins, item)
    return np.where(bins >= item, (count * item) / bins, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    remainder = bins % item
    return np.where(bins >= item, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    remainder = bins % item
    remaining_capacity = bins - item
    priority_score = -remainder * remaining_capacity
    return np.where(bins >= item, priority_score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    fit_mask = bins >= item
    num_items = np.floor_divide(bins, item)
    leftover = bins - num_items * item
    return np.where(fit_mask, num_items * np.exp(-leftover ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    penalty_factor = 0.9
    remaining = bins - item
    return np.where(bins >= item, remaining * (penalty_factor ** remaining), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    remainder = bins % item
    diff = np.abs(remainder - (item / 2))
    return np.where(bins >= item, -diff, -np.inf)
